def cjson(v):return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":"))
def logical_digest(db,table):
    cols=[r[1] for r in db.execute(f'PRAGMA table_info("{table}")')];h=hashlib.sha256();sel=", ".join(f'"{c}"' for c in cols)
    for row in db.execute(f'SELECT {sel} FROM "{table}" ORDER BY rowid'):
        h.update(cjson(list(row)).encode("utf-8"));h.update(b"\n")
    return h.hexdigest()
